This Terraform configuration creates an AWS Lambda Layer Version from a local ZIP archive named `lambda_layer_payload.zip`. It configures the AWS provider, defines variables with defaults, and publishes the Lambda layer so it can be attached to Lambda functions.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lambda Layer Version will be created."
  type        = string
  default     = "us-east-1"
}

variable "lambda_layer_name" {
  description = "Name of the Lambda layer."
  type        = string
  default     = "example-lambda-layer"
}

variable "lambda_layer_zip_path" {
  description = "Path to the Lambda layer ZIP file."
  type        = string
  default     = "lambda_layer_payload.zip"
}

